from pathlib import Path
import json,html,hashlib,zipfile
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/CeilingWorker_2026-11-08/Revision18'
captions=[
('01_first_clue.png','Сначала — пустой нижний стол','Убраны монитор, бумаги и кресло выбранного рабочего места. Корпус стола и компьютер внизу сохранены.','В игре ещё нужно пройти путь от двери: внимание к пустому столу нельзя подтвердить одним постановочным кадром.'),
('02_player_looks_up.png','Кабинет наверху','Полноразмерный сотрудник в собственном кабинете на ковролине. Монитор сдвинут вбок, чтобы открыть лицо.','Новый кабинет пока существует только в Blender. Размещение в самой игре и отсутствие пересечений с персонажами ещё не проверены.'),
('03_three_quarter.png','Объём и боковой проход','Кабинет имеет толщину, перегородку, кресло и тумбу. Это отдельное пространство над нижней мебелью.','Офисное окружение перенесено по замерам. Сложные детали старой мебели в Blender представлены приближённой геометрией.'),
('04_face.png','Лицо и медленный поворот','Анатомическая форма головы, уши, веки, отдельные глаза, волосы с пробором. Черты сохраняются при повороте.','Следующая художественная доработка — кожа, веки и воротник. Это первый вариант внешности для совместного просмотра.'),
('05_hands.png','Кисти и клавиатура','Кисти развёрнуты по анатомической плоскости ладоней. Предплечья соединяются с запястьями, края рукавов прикрыты манжетами.','В девяти выбранных состояниях минимальный зазор над клавишами около 3 мм. Поштучную работу пальцев и нажатие клавиш предстоит доработать.'),
('06_upper_shelf.png','Календарь и стикеры','Крупный план календаря за ноябрь 2026 года. Край полки и папки видны снизу; растение можно рассмотреть на общих кадрах.','У календаря правильные 30 дат и расположение дней недели. В игровом варианте мелкие надписи потребуют проверки читаемости.'),
('07_ceiling_edge.png','Граница в потолке','Приподнятые плиты и тёмный край вокруг ковролина показывают толщину перекрытия.','В игровой реализации придётся временно закрывать или разделять исходные плиты, затем точно восстанавливать их при смене раунда.'),
('08_monitor_plan.png','План настоящего офиса','На мониторе нарисованы измеренные комнаты и коридоры, а не декоративная сетка.','Две метки сейчас иллюстративные. Подключение к реальным игрокам, поворотам и высоте остаётся отдельным шагом.'),
('09_wardrobe.png','Одежда и посадка','Белая хлопковая рубашка, ослабленный тёмный галстук, брюки и кожаная обувь. Рабочая поза слегка сутулая.','Нужны дальнейшие позы для кружки, мыши и чтения документов, а также проверка одежды при этих движениях.'),
('10_full_scene.png','Масштаб в комнате','Общий вид помогает сопоставить нижний стол, высоту потолка и размер верхнего кабинета.','Эта сцена — художественная проверка масштаба. Игровые коллизии, совместный режим, звук и сброс ещё не тестировались.'),
('11_upright_character_inspection.png','Отдельный осмотр внешности','Тот же сотрудник временно показан в обычном положении для удобного осмотра лица.','Только этот кадр развёрнут для осмотра. В аномалии кабинет и человек перевёрнуты; исходный файл этим кадром не изменён.')]
for filename,*_ in captions:assert(OUT/filename).is_file(),filename
assert(OUT/'Attention_Example_10sec.mp4').is_file()
cards=''.join(f'<figure><button class="picture" data-index="{i}" aria-label="Открыть кадр {i+1}"><img loading="lazy" src="{html.escape(f)}" alt="{html.escape(title)}"></button><figcaption><span>{i+1:02d} / BLENDER</span><h2>{html.escape(title)}</h2><p>{html.escape(desc)}</p><p class="next">{html.escape(note)}</p></figcaption></figure>'for i,(f,title,desc,note)in enumerate(captions))
data=json.dumps([{'file':f,'title':t,'description':d,'note':n}for f,t,d,n in captions],ensure_ascii=False)
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Сотрудник на потолке — первый макет</title><style>
*{box-sizing:border-box}body{margin:0;background:#101716;color:#edf1e9;font:17px/1.6 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:36px 24px}header{max-width:960px;margin-bottom:32px}header .eyebrow{color:#b2c898;letter-spacing:.12em;font-size:12px}h1{font-size:clamp(32px,5vw,58px);line-height:1.12;font-weight:650;margin:18px 0}h2{font-size:22px;line-height:1.3;margin:8px 0 14px}p{color:#c0ccc5}.status{border-left:3px solid #bac890;padding:12px 20px;background:#1d2722;border-radius:0 8px 8px 0}video{width:100%;max-height:740px;background:#000;border-radius:12px}section{margin:40px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}figure{margin:0;background:#19221f;border-radius:12px;overflow:hidden}figure .picture{padding:0;width:100%;border:0;display:block;cursor:zoom-in;background:#000}figure img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block}figcaption{padding:24px}figcaption span{font-size:12px;letter-spacing:.14em;color:#b4c899}.next{font-size:14px;color:#95a99e;border-top:1px solid #354139;padding-top:16px}a{color:#c7d8ad}dialog{width:min(1240px,96vw);max-height:94vh;overflow:auto;background:#111b16;color:#edf1e9;border:1px solid #607064;padding:16px;border-radius:14px}dialog::backdrop{background:#000d}dialog img{display:block;max-width:100%;max-height:68vh;margin:auto;object-fit:contain}.controls{display:flex;justify-content:space-between;gap:12px;margin-top:12px}.controls button{background:#273a2b;color:#edf1e9;border:1px solid #647b62;border-radius:7px;padding:8px 16px;font:inherit;cursor:pointer}dialog p{margin:12px 0}.files{display:flex;gap:24px;flex-wrap:wrap}footer{font-size:14px;margin-top:40px;color:#92a397}@media(max-width:760px){main{padding:24px 16px}.grid{grid-template-columns:1fr;gap:20px}figcaption{padding:18px}.controls button{padding:8px 10px}dialog img{max-height:58vh}}
</style><main><header><div class="eyebrow">КОНТУР · СОТРУДНИК НА ПОТОЛКЕ · V18 · 8 НОЯБРЯ 2026</div><h1>Спокойная работа.<br>Неправильная сторона комнаты.</h1><p>Мужчина около 33 лет, белая рубашка, пробор и едва заметная улыбка. Пустой стол внизу, маленький кабинет на потолке, тусклый жёлтый свет.</p><div class="status">Это первый подробный макет Blender. В карту Roblox он ещё не установлен. Текущая карта v17 и законченная кровавая аномалия сохранены без изменений.</div></header><section><h2>Пример реакции · 10 секунд</h2><p>Печать, плавная остановка, поворот головы, взгляд вслед и возврат к работе. Ролик без звука. Это заранее запечённый пример движения, а не уже подключённое отслеживание игрового персонажа.</p><video controls preload="metadata" poster="02_player_looks_up.png" src="Attention_Example_10sec.mp4"></video></section><section class="grid">'''+cards+'''</section><section><h2>Что согласовано и что дальше</h2><p>Сотрудник не убивает. Реагирует после 1,5 секунды взгляда. Кабинет исчезает при обычном переходе уровня. Выбраны связь ламп и ящика, живой план офиса, безопасное падение предметов за край, папки и растение на полке.</p><p>Для нижнего ящика задан отдельный вопрос: под выбранным столом сейчас компьютер, а штатная тумба находится у другого рабочего места. Решение о её размещении ещё не принято. Следующий этап — движения с кружкой и документами, игровые связи, локальная геометрия и материалы Roblox, затем одиночная и совместная проверка.</p><div class="files"><a href="Ceiling_Office_Character_Study_v18.blend">Редактируемая сцена Blender</a><a href="Art_Stage_Check.json">Проверка художественного этапа</a><a href="Hand_Contact_Check.json">Контакт кистей с клавиатурой</a><a href="Head_Coherence_Check.json">Целостность головы при движении</a></div></section><footer>Анатомическая основа: <a href="https://www.blender.org/download/demo-files/">Blender Studio Human Base Meshes 1.4.1, CC0</a>. Одежда, кабинет, материалы и постановка доработаны локально. Некоторые мелкие формы мебели исходной карты в окружении Blender заменены измеренными габаритами. Новых загрузок и публикации ресурсов Roblox нет.</footer></main><dialog><img id="large" alt=""><div class="controls"><button id="previous">← Назад</button><button id="close">Закрыть</button><button id="next">Дальше →</button></div><h2 id="title"></h2><p id="description"></p><p id="note" class="next"></p></dialog><script>
const frames='''+data+''',dialog=document.querySelector('dialog');let current=0;function show(i){current=(i+frames.length)%frames.length;const f=frames[current];document.querySelector('#large').src=f.file;document.querySelector('#large').alt=f.title;document.querySelector('#title').textContent=`${current+1} / ${frames.length} · ${f.title}`;document.querySelector('#description').textContent=f.description;document.querySelector('#note').textContent=f.note}document.querySelectorAll('.picture').forEach(b=>b.onclick=()=>{show(Number(b.dataset.index));dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#previous').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(dialog.open&&e.key==='ArrowRight')show(current+1);if(dialog.open&&e.key==='ArrowLeft')show(current-1)});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
</script></html>'''
(OUT/'Просмотр_сотрудника_v18.html').write_text(page)
(OUT/'Captions.json').write_text(data)
manifest={'stage':'First Blender art review; no native map changes','files':{}}
for f in OUT.iterdir():
    if f.suffix not in ['.png','.blend','.mp4','.html','.json']or f.name=='Review_Manifest.json':continue
    manifest['files'][f.name]={'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()}
(OUT/'Review_Manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
archive=OUT.parent/'Ceiling_Worker_v18_Blender_Review.zip'
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=5)as z:
    for name in list(manifest['files'])+['Review_Manifest.json']:z.write(OUT/name,'Ceiling_Worker_v18/'+name)
print(json.dumps({'gallery':str(OUT/'Просмотр_сотрудника_v18.html'),'images':len(captions),'zip':str(archive),'bytes':archive.stat().st_size},ensure_ascii=False))
